import{Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{printedArtwork}from'../../modeling/artwork.js';import{portQuaternion}from'../../modeling/parts.js';import{THREE,mesh,box,extrude,roundedRect,circleHole,annulus}from'./geometry.js';import data from'./geometry-data.js';import{spec}from'./dimensions.js';import{grove,usbA,usbC,microSD}from'./connectors.js';import{NativeButton}from'./NativeButton.js';import{Clip}from'./accessories.js';
const rearUrl=new URL('./artwork/rear.png',import.meta.url).href;
function board(host){const s=roundedRect(20.4,44,1,{cy:-.2});for(let i=0;i<4;i++)circleHole(s,(i-1.5)*2,-18.26,.34);for(let i=0;i<4;i++)circleHole(s,(i-1.5)*2.5,10.86,.47);for(const x of[-6.2,6.2])s.holes.push(roundedRect(.85,2.65,.07,{cx:x,cy:12.46,path:new THREE.Path(),clockwise:true}));const pcb=mesh(host.body,extrude(s,.8),materials.plastic(0x263c2c,{roughness:.91}),[0,0,-.8],'U078-USB actual main PCB;hidden outline/installation inferred'),lands=[];for(let i=0;i<4;i++)lands.push(mesh(host.body,annulus(.6,.34,.035),materials.metal(0xb5a16a),[(i-1.5)*2,-18.26,0],'U078-USB real HY2.0 annular solder pad'));
 const dark=materials.plastic(0x222820),metal=materials.metal(0xaeb2a4),packages=[],ends=[];
 for(const[name,x,y,w,h,t]of[['SSD202D',0,2,10,10,1.8],['DDR3',-4.7,-9,5.2,7,1.4],['NAND',4.5,-8,5,7.4,1.3],['Wi-Fi',4,17,3.8,3.8,.9]]){const q=box(host.body,[w,h,t],[x,y,t/2],dark,'U078-USB '+name+' concealed fixed package envelope');q.userData={role:'concealed-package',installationInferred:true};packages.push(q);for(const sx of[-1,1])for(let n=0;n<4;n++)ends.push(box(host.body,[.25,.45,.12],[x+sx*(w/2+.08),y+(n-1.5)*.8,.06],metal,'U078-USB fixed package physical termination'));}
 const passives=[];for(let i=0;i<12;i++){const x=(i%2?1:-1)*8,y=16-Math.floor(i/2)*5;passives.push(box(host.body,[1.1,.7,.45],[x,y,.225],materials.plastic(0xb6a285),'U078-USB concealed passive envelope'));for(const sx of[-1,1])ends.push(box(host.body,[.2,.7,.12],[x+sx*.48,y,.06],metal,'U078-USB passive termination'));}
 const indicators=[];for(const[x,c]of[[-1.4,0x922d28],[1.4,0xcccfc4]])indicators.push(box(host.body,[1.4,1,.6],[x,18.5,.3],materials.plastic(c),'U078-USB internal nonemissive indicator carrier;external light path unconfirmed'));
 const switchBase=box(host.body,[5.3,2.2,3.8],[0,20.6,1.9],dark,'U078-USB actual fixed internal top-end switch package envelope'),switchFrame=box(host.body,[5.5,1.7,.3],[0,20.6,3.95],metal,'U078-USB fixed switch metal retainer'),switchTerminals=[];for(const x of[-2,2])for(const y of[19.8,21.4])switchTerminals.push(box(host.body,[.55,.65,.18],[x,y,.09],metal,'U078-USB fixed switch solder terminal'));
 const follower=box(host.body,[2.5,.7,1.6],[0,22.05,1.3],materials.plastic(0xb7bcb0),'U078-USB only actual internal switch plunger follows native tongue');
 return{pcb,lands,packages,ends,passives,indicators,switchBase,switchFrame,switchTerminals,follower};}
function fanCarrier(host){const frame=new THREE.Group();frame.position.fromArray(spec.fan.position);frame.name='U078-USB fixed concealed cooling assembly envelope;rotor not established';host.body.add(frame);const m=materials.plastic(0x202621,{roughness:.87}),housing=mesh(frame,annulus(7.1,5.7,1.8),m,[0,0,-1.6],'U078-USB fixed fan surrounding carrier behind real native grille'),backing=mesh(frame,new THREE.CylinderGeometry(5.7,5.7,.7,48).rotateX(Math.PI/2),m,[0,0,-.95],'U078-USB opaque retained cooling-unit backing seen through native grille'),hub=mesh(frame,new THREE.CylinderGeometry(2,2,1.4,40).rotateX(Math.PI/2),m,[0,0,-.6],'U078-USB fixed concealed motor carrier envelope'),support=box(frame,[13,13,.8],[0,0,.4],materials.metal(0x5b6258),'U078-USB fixed cooling assembly support beneath PCB');const posts=[];for(const x of[-5.8,5.8])for(const y of[-5.8,5.8])posts.push(mesh(frame,new THREE.CylinderGeometry(.6,.6,5,24).rotateX(Math.PI/2),m,[x,y,3.3],'U078-USB inferred fixed cooling-to-PCB retaining spacer'));return{frame,housing,backing,hub,support,posts,rotor:null,joint:null};}
function label(host){const w=spec.label.size[0],h=spec.label.size[1],s=new THREE.Shape();s.moveTo(-w/2,h/2);s.lineTo(w/2,h/2);s.lineTo(w/2,-h/2);s.lineTo(6.4,-h/2);s.bezierCurveTo(4.4,-9.3,2.3,-9.3,0,-9.3);s.bezierCurveTo(-2.3,-9.3,-4.4,-9.3,-6.4,-h/2);s.lineTo(-w/2,-h/2);s.closePath();const film=mesh(host.body,extrude(s,.035),materials.plastic(0xeeeedd,{roughness:.86}),spec.label.position,'U078-USB independent physical die-cut manufacturer adhesive film');film.userData={role:'physical-label-substrate',thicknessMm:.035,registrationInferred:true};const ink=printedArtwork(host,{target:film,url:rearUrl,size:spec.label.size,position:spec.label.position,face:'back',depth:.1,name:'U078-USB own readable rear manufacturing label redraw;variable identifiers omitted',artworkKind:'reference-redraw'});return{film,ink};}
export function buildUnitV2Usb(host,options=host.options){const opts={...spec.defaults,...options};if(typeof opts.clip!=='boolean')throw new TypeError('UnitV2-USB clip must be boolean');const parts=addCadParts(host,data.slice(0,2),{shell:materials.plastic(0x262d28,{roughness:.67,transparent:true,opacity:.68,depthWrite:false})}),front=parts[data[0].name],rear=parts[data[1].name],pcb=board(host),input=grove(host),usba=usbA(host),usbc=usbC(host),storage=microSD(host),cooling=fanCarrier(host),user=host.add(new NativeButton(front,pcb.follower));
 const mount=host.add(new Port({id:'mount',label:'Own supplied static rear clip',connector:spec.mount.connector,position:spec.mount.position,quaternion:portQuaternion('back'),hitSize:[27,1,28],meta:{role:'visual-connector',face:'back',scope:'Exact own native static clip only;no generic LEGO/HAT fit,hinge or electrical routing',datumSource:'Own native selected complete3316-face part in source installation pose;port datum inferred for attachment API'}}));
 const labels=label(host);host.unitV2UsbAssembly={parts,front,rear,board:pcb,input,usba,usbc,storage,cooling,user,mount,labels,options:opts};host.unitStickers=labels.ink??[];if(opts.clip)mount.attach(Clip);
}
